    FormName	formName	= new URLUtility().getQueryParamValue('FormName');
    CompanyId   cmpName		= new URLUtility().getQueryParamValue('cmp');
    str			baseUrl		= EnvironmentFactory::GetApplicationEnvironment().Infrastructure.HostUrl;
    //Call the form using a Menu Item
    Args	Args = new Args(formName);

    formRun = New FormRun(Args);
    formRun.init();
    formRun.run();
    formRun.wait();


